def fibonacci(n):
    """生成斐波那契数列的前n项"""
    fib_sequence = [0, 1]
    for i in range(2, n):
        next_value = fib_sequence[i-1] + fib_sequence[i-2]
        fib_sequence.append(next_value)
    return fib_sequence[:n]

try:
