class Config {
public:
    string support_chat_dir;
    string transaction_dir;
    string output_dir;
    string db_path;
    vector<string> products;

    Config(const string& config_path) {
        ifstream configFile(config_path);
        if (!configFile.is_open()) {
            throw runtime_error("Could not open config file");
        }

        Json::CharReaderBuilder builder;
        Json::CharReaderBuilder::enableIPOByDefault(builder);
        string errs;
