        if (!parsingSuccessful) {
            throw runtime_error("Failed to parse config file: " + errs);
        }

        support_chat_dir = root.get("support_chat_dir", "").asString();
        transaction_dir = root.get("transaction_dir", "").asString();
        output_dir = root.get("output_dir", "").asString();
        db_path = root.get("db_path", "").asString();

        Json::Value productsArray = root.get("products", Json::Value(Json::arrayValue));
        for (const auto& product : productsArray) {
            products.push_back(product.asString());
        }
    }
};

// Database helper class
class Database {
private:
    sqlite3* db;
    mutex dbMutex;

    int callback(void* data, int argc, char** argv, char** azColName) {
        // Not used in this implementation
        return 0;
    }

public:
    Database(const string& dbPath) {
        int rc = sqlite3_open(dbPath.c_str(), &db);
        if (rc != SQLITE_OK) {
            throw runtime_error("Cannot open database: " + string(sqlite3_errmsg(db)));
        }
    }

    ~Database() {
        if (db) {
            sqlite3_close(db);
        }
    }

    void execute(const string& sql) {
        lock_guard<mutex> lock(dbMutex);
        char* errMsg = nullptr;
        int rc = sqlite3_exec(db, sql.c_str(), callback, nullptr, &errMsg);
        if (rc != SQLITE_OK) {
            throw runtime_error("SQL error: " + string(errMsg));
            sqlite3_free(errMsg);
        }
    }

    vector<vector<string>> query(const string& sql) {
        lock_guard<mutex> lock(dbMutex);
        vector<vector<string>> result;
        sqlite3_stmt* stmt;

        int rc = sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr);
        if (rc != SQLITE_OK) {
            throw runtime_error("Failed to prepare statement: " + string(sqlite3_errmsg(db)));
        }

        result = executeQuery(stmt, result);
        sqlite3_finalize(stmt);
        return result;
    }

private:
    vector<vector<string>> executeQuery(sqlite3_stmt* stmt, vector<vector<string>>& result) {
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            vector<string> row;
            for (int i = 0; i < sqlite3_column_count(stmt); i++) {
                string columnName(sqlite3_column_name(stmt, i));
                string value((char*)sqlite3_column_text(stmt, i));
                row.push_back(value);
            }
            result.push_back(row);
        }
        return result;
    }
};

// Data cleaning functions
string standardizeTimestamp(const string& timestamp) {
    // Try to parse various formats
    try {
        // If it looks like a Unix timestamp
        if (timestamp.find('.') != string::npos && isdigit(timestamp[0])) {
            time_t tt = (time_t)(stod(timestamp));
            return asctime(localtime(&tt));
        }

        // If it has date format
        if (timestamp.find('-') != string::npos && timestamp.find('T') != string::npos) {
            // ISO 8601 format
            return timestamp;
        }

        // If it has basic date format
        if (timestamp.find('/') != string::npos) {
            // MM/DD/YYYY format
            return timestamp;
        }

        // If it's just a number, assume timestamp
        return timestamp;
    } catch (...) {
        return timestamp;
    }
}

string standardizeText(const string& text) {
    if (text.empty()) return "";

    // Convert to lowercase
    string lowerText;
    for (char c : text) {
        lowerText += tolower(c);
    }

    // Remove special characters except letters, numbers and spaces
    string cleanText;
    for (char c : lowerText) {
        if (isalnum(c) || c == ' ' || c == '.' || c == ',' || c == '-' || c == '_' || c == '(' || c == ')') {
            cleanText += c;
        }
    }

    // Remove extra spaces
    regex spaceRegex("\\s+");
    cleanText = regex_replace(cleanText, spaceRegex, " ");
    if (cleanText.front() == ' ') cleanText.erase(0, 1);
    if (cleanText.back() == ' ') cleanText.pop_back();

    return cleanText;
}

bool removeDuplicates(const vector<string>& list) {
    set<string> uniqueSet(list.begin(), list.end());
    return uniqueSet.size() < list.size();
}

vector<string> handleMissingValues(const vector<string>& data, const string& defaultValue) {
    vector<string> result;
    for (const string& value : data) {
        if (value.empty()) {
            result.push_back(defaultValue);
        } else {
            result.push_back(value);
        }
    }
    return result;
}

// Data processing functions
vector<string> extractDates(const string& text) {
    vector<string> dates;
    regex dateRegex("(\\d{4}[-/]\\d{2}[-/]\\d{2})|([A-Za-z]+\\s\\d{1,2},\\s\\d{4})");
    smatch matches;

    if (regex_search(text, matches, dateRegex)) {
        for (size_t i = 0; i < matches.size(); ++i) {
            if (i % 2 == 1) { // Odd indices are the matches
                dates.push_back(matches[i].str());
            }
        }
    }
    return dates;
}

vector<string> extractEntities(const string& text) {
    vector<string> entities;
    // Simple entity extraction - in a real system, you'd use NER
    regex entityRegex("(\\d+\\.\\d+)|(\\d+)|(http:\\/\\/|https:\\/\\/\\S+)|(\\$\\d+(\\.\\d+)?)");
    smatch matches;

    while (regex_search(text, matches, entityRegex)) {
        entities.push_back(matches.str());
        text = matches.suffix().str();
    }

    return entities;
}

