private:
    // Helper function to execute query and collect results
    vector<vector<string>> executeQuery(sqlite3_stmt* stmt, vector<vector<string>>& result) {
        // Process each row of the query result
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            vector<string> row;
            int columnCount = sqlite3_column_count(stmt);

            // Add each column value to the row
            for (int i = 0; i < columnCount; i++) {
                string columnName(sqlite3_column_name(stmt, i));
                string value((char*)sqlite3_column_text(stmt, i));
                row.push_back(value);
            }

            // Add row to results
            result.push_back(row);
        }
        return result;
    }
};

// Function to standardize timestamp formats
string standardizeTimestamp(const string& timestamp) {
    /**
     * Standardizes various timestamp formats to a common format.
     * 
     * This function attempts to parse timestamps in multiple formats:
     * 1. Unix timestamps (e.g., 1625097820.1234)
     * 2. ISO 8601 format (e.g., 2021-07-01T12:34:56.789Z)
     * 3. Common date formats (e.g., MM/DD/YYYY, YYYY-MM-DD)
     * 4. Basic date formats (e.g., July 1, 2021)
     * 
     * If the timestamp cannot be parsed, it returns the original string.
     * 
     * @param timestamp The timestamp string to standardize
     * @return A standardized timestamp string or the original if parsing fails
     */
    try {
        // Try to parse as Unix timestamp with milliseconds
        if (timestamp.find('.') != string::npos && isdigit(timestamp[0])) {
            time_t tt = (time_t)(stod(timestamp));
            return asctime(localtime(&tt)); // Convert to human-readable format
        }

        // Handle ISO 8601 format (e.g., 2021-07-01T12:34:56.789Z)
        if (timestamp.find('-') != string::npos && timestamp.find('T') != string::npos) {
            // This implementation simply returns the original format
            return timestamp;
        }

        // Handle MM/DD/YYYY format
        if (timestamp.find('/') != string::npos) {
            // This implementation simply returns the original format
            return timestamp;
        }

        // Default case - return the original timestamp
        return timestamp;
    } catch (...) {
        // Return original timestamp if any error occurs during processing
        return timestamp;
    }
}

// Function to standardize and clean text data
string standardizeText(const string& text) {
    /**
     * Cleans and standardizes text data by:
     * 1. Converting to lowercase
     * 2. Removing special characters except letters, numbers, and selected punctuation
     * 3. Normalizing whitespace
     * 
     * This function is designed to prepare text for analysis by removing noise
     * while preserving meaningful information.
     * 
     * @param text The text to standardize
     * @return Cleaned and standardized text
     */
    if (text.empty()) return ""; // Return empty string for empty input

    // Convert text to lowercase
    string lowerText;
    for (char c : text) {
        lowerText += tolower(c);
    }

    // Keep only allowed characters (alphanumeric, spaces, and selected punctuation)
    string cleanText;
    for (char c : lowerText) {
        if (isalnum(c) || c == ' ' || c == '.' || c == ',' || c == '-' || 
            c == '_' || c == '(' || c == ')') {
            cleanText += c; // Add character if it's allowed
        }
    }

    // Normalize whitespace (remove extra spaces)
    regex spaceRegex("\\s+");
    cleanText = regex_replace(cleanText, spaceRegex, " ");

    // Remove leading/trailing spaces
    if (!cleanText.empty() && cleanText.front() == ' ') {
        cleanText.erase(0, 1); // Remove leading space
    }
    if (!cleanText.empty() && cleanText.back() == ' ') {
        cleanText.pop_back(); // Remove trailing space
    }

    return cleanText;
}

// Function to check for duplicate items in a list
bool removeDuplicates(const vector<string>& list) {
    /**
     * Checks if there are duplicate items in a list.
     * 
     * This function uses a set to determine if the number of unique items
     * is less than the total number of items in the list.
     * 
     * @param list The list to check for duplicates
     * @return True if duplicates exist, false otherwise
     */
    set<string> uniqueSet(list.begin(), list.end());
    return (uniqueSet.size() < list.size());
}

// Function to handle missing values in a dataset
vector<string> handleMissingValues(const vector<string>& data, const string& defaultValue) {
    /**
     * Replaces empty or missing values in a dataset with a default value.
     * 
     * This function iterates through the input data and replaces any empty
     * string with the specified default value.
     * 
     * @param data The input dataset with potential missing values
     * @param defaultValue The value to use for missing entries
     * @return A new dataset with missing values replaced
     */
    vector<string> result;
    for (const string& value : data) {
        if (value.empty()) {
            result.push_back(defaultValue); // Replace missing value
        } else {
            result.push_back(value); // Keep original value
        }
    }
    return result;
}

// Function to extract dates from text
vector<string> extractDates(const string& text) {
    /**
     * Extracts date patterns from a given text string.
     * 
     * This function uses regular expressions to identify potential date
     * patterns in the input text. It supports formats like YYYY-MM-DD,
     * MM/DD/YYYY, and textual dates (e.g., "July 1, 2021").
     * 
     * @param text The text to search for dates
     * @return A vector of extracted date strings
     */
    vector<string> dates;
    // Regular expression to match date patterns
    regex dateRegex("(\\d{4}[-/]\\d{2}[-/]\\d{2})|([A-Za-z]+\\s\\d{1,2},\\s\\d{4})");
    smatch matches;

    // Search for date matches in the text
    if (regex_search(text, matches, dateRegex)) {
        // Process each match
        for (size_t i = 0; i < matches.size(); ++i) {
            if (i % 2 == 1) { // Odd indices are the matches (1-indexed in smatch)
                dates.push_back(matches[i].str());
            }
        }
    }
    return dates;
}

// Function to extract entities from text
vector<string> extractEntities(const string& text) {
    /**
     * Extracts entities (numbers, URLs, and prices) from text.
     * 
     * This function uses regular expressions to identify potential entities
     * in the input text. It supports formats like numbers, URLs, and prices.
     * 
     * @param text The text to search for entities
     * @return A vector of extracted entity strings
     */
    vector<string> entities;
    // Regular expression to match entities
    regex entityRegex("(\\d+\\.\\d+)|(\\d+)|(http:\\/\\/|https:\\/\\/\\S+)|(\\$\\d+(\\.\\d+)?)");
    smatch matches;

    // Search for entities in the text
    while (regex_search(text, matches, entityRegex)) {
        entities.push_back(matches.str()); // Add found entity
        text = matches.suffix().str(); // Continue searching from the end of the match
    }

    return entities;
}

