    vector<string> listFiles(const string& directory) {
        /**
         * Lists all regular files in a specified directory.
         * 
         * This function uses the POSIX directory API to list files in the
         * specified directory, filtering for regular files.
         * 
         * @param directory The directory to search
         * @return A vector of file paths in the directory
         */
        vector<string> files;
        if (directory.empty()) return files; // Return empty list if directory is not specified

        // Open the directory
        DIR* dir;
        struct dirent* ent;
        if ((dir = opendir(directory.c_str())) != NULL) {
            // Read each entry in the directory
            while ((ent = readdir(dir)) != NULL) {
                if (ent->d_type == DT_REG) { // Check if it's a regular file
                    string filename = directory + "/" + ent->d_name;
                    files.push_back(filename); // Add to list of files
                }
            }
            closedir(dir); // Close the directory
        }
        return files;
    }
};

// Thread-safe console output class
class Console {
private:
    mutex mtx;                   // Mutex for thread-safe console access

public:
    // Function to print text to console
    void print(const string& text) {
        /**
         * Prints text to the console in a thread-safe manner.
         * 
         * This function uses a mutex to ensure that multiple threads
         * can print to the console without interference.
         * 
         * @param text The text to print
         */
        lock_guard<mutex> lock(mtx); // Lock mutex before printing
        cout << text;
        cout.flush(); // Ensure immediate output
    }

    // Function to print text and newline to console
    void println(const string& text) {
        /**
         * Prints text followed by a newline to the console in a thread-safe manner.
         * 
         * This function uses a mutex to ensure that multiple threads
         * can print to the console without interference.
         * 
         * @param text The text to print
         */
        lock_guard<mutex> lock(mtx); // Lock mutex before printing
        cout << text << endl;
    }
};

