Here's the complete C++ code with detailed comments explaining each function and process:

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <cstdlib> // For atof()

using namespace std;

// Function to open and read numbers from a file
// Parameters: 
//   filename - name of the input file
//   numbers - reference to a vector that will store the read numbers
// Returns: 
//   true if successful, false otherwise
bool readNumbersFromFile(const string& filename, vector<double>& numbers) {
    // Open the file for reading
    ifstream inputFile(filename);

    // Check if file was successfully opened
    if (!inputFile.is_open()) {
        cerr << "Error: Could not open input file: " << filename << endl;
        return false;
    }

    // Read each line from the file
    string line;
    while (getline(inputFile, line)) {
        // Skip empty lines
        if (line.empty()) continue;

        // Convert the line to a double and add to numbers vector
        numbers.push_back(atof(line.c_str()));
    }

    // Close the file
    inputFile.close();
    return true;
}

// Function to calculate the average of numbers in a vector
// Parameters:
//   numbers - vector containing the numbers to average
// Returns:
//   The calculated average as a double
// Throws:
//   runtime_error if the vector is empty
double calculateAverage(const vector<double>& numbers) {
    // Check if we have numbers to average
    if (numbers.empty()) {
        throw runtime_error("Error: No numbers to calculate average.");
    }

    // Calculate the sum of all numbers
    double sum = 0.0;
    for (double num : numbers) {
        sum += num;
    }

    // Calculate and return the average
    return sum / numbers.size();
}

// Function to write results to an output file
// Parameters:
//   filename - name of the output file
//   average - the calculated average to write
// Returns:
//   true if successful, false otherwise
bool writeResultsToFile(const string& filename, double average) {
    // Open the output file
    ofstream outputFile(filename);

    // Check if file was successfully opened
    if (!outputFile.is_open()) {
        cerr << "Error: Could not create output file: " << filename << endl;
        return false;
    }

    // Write the average to the file with 2 decimal places
    outputFile << "Average: " << fixed << setprecision(2) << average << endl;

    // Close the file
    outputFile.close();
    return true;
}

// Main function that coordinates all operations
int main() {
    // Define input and output file names
    const string INPUT_FILE = "input.txt";
    const string OUTPUT_FILE = "output.txt";

    // Vector to store the numbers read from the file
    vector<double> numbers;

    // Step 1: Read numbers from the input file
    if (!readNumbersFromFile(INPUT_FILE, numbers)) {
        cerr << "Program terminated due to file reading error." << endl;
        return 1;
    }

    // Step 2: Calculate the average
    double average;
    try {
        average = calculateAverage(numbers);
    } catch (const exception& e) {
        cerr << e.what() << endl;
        return 1;
    }

    // Step 3: Write results to output file and display on console
    if (!writeResultsToFile(OUTPUT_FILE, average)) {
        cerr << "Program terminated due to file writing error." << endl;
        return 1;
    }

    // Output the average to the console
    cout << "Average of numbers: " << fixed << setprecision(2) << average << endl;

    return 0;
}
